class Solution { public:int miceAndCheese(vector<int>& reward1,vector<int>& reward2,int k){vector<int> difference(reward1.size());int answer=0;for(int i=0;i<(int)reward1.size();++i){answer+=reward2[i];difference[i]=reward1[i]-reward2[i];}nth_element(difference.begin(),difference.end()-k,difference.end());for(int i=difference.size()-k;i<(int)difference.size();++i)answer+=difference[i];return answer;} };
